CREATE OR REPLACE FUNCTION public.follow_user(p_followed_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_follower_id uuid;
  v_follower_name text;
  v_follow_id uuid;
begin
  v_follower_id := auth.uid();

  if v_follower_id is null then
    raise exception '┘è╪ش╪ذ ╪ز╪│╪ش┘è┘ ╪د┘╪»╪«┘ê┘ ╪ث┘ê┘╪د┘ï';
  end if;

  if p_followed_id is null or p_followed_id = v_follower_id then
    raise exception '┘╪د ┘è┘à┘â┘┘â ┘à╪ز╪د╪ذ╪╣╪ر ┘ç╪░╪د ╪د┘╪ص╪│╪د╪ذ';
  end if;

  if not exists (
    select 1 from public.profiles
    where id = p_followed_id
  ) then
    raise exception '╪د┘╪ص╪│╪د╪ذ ╪║┘è╪▒ ┘à┘ê╪ش┘ê╪»';
  end if;

  insert into public.user_follows (follower_id, followed_id)
  values (v_follower_id, p_followed_id)
  on conflict (follower_id, followed_id) do nothing
  returning id into v_follow_id;

  -- ╪ح╪░╪د ┘â╪د┘╪ز ╪د┘┘à╪ز╪د╪ذ╪╣╪ر ┘à┘ê╪ش┘ê╪»╪ر ┘à╪│╪ذ┘é╪د┘ï╪î ┘╪د ┘╪▒╪│┘ ╪ح╪┤╪╣╪د╪▒╪د┘ï ╪ش╪»┘è╪»╪د┘ï
  if v_follow_id is null then
    return false;
  end if;

  select coalesce(nullif(display_name, ''), '┘à╪│╪ز╪«╪»┘à ╪ش╪»┘è╪»')
  into v_follower_name
  from public.profiles
  where id = v_follower_id;

  perform public.create_sale_notification(
    p_followed_id,
    '┘à╪ز╪د╪ذ╪╣ ╪ش╪»┘è╪»',
    v_follower_name || ' ╪ذ╪»╪ث ╪ذ┘à╪ز╪د╪ذ╪╣╪ز┘â',
    '/user/' || v_follower_id::text
  );

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.unfollow_user(p_followed_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_follower_id uuid;
  v_deleted_count integer;
begin
  v_follower_id := auth.uid();

  if v_follower_id is null then
    raise exception '┘è╪ش╪ذ ╪ز╪│╪ش┘è┘ ╪د┘╪»╪«┘ê┘ ╪ث┘ê┘╪د┘ï';
  end if;

  delete from public.user_follows
  where follower_id = v_follower_id
    and followed_id = p_followed_id;

  get diagnostics v_deleted_count = row_count;

  return v_deleted_count > 0;
end;
$function$
